/* Glass's material: everything drawn is made of these names, and nothing
   else. Colours come in a light and a dark; type is a serif to read in and a
   sans for what stands around the reading; the measure keeps a line short
   enough to read. */

:root {
  --ground: #fbfaf7;
  --raised: #ffffff;
  --ink: #23211d;
  --quiet: #6f6a61;
  --line: #e4e0d7;
  --accent: #3d5a80;

  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --text: 18px;
  --leading: 1.6;
  --leading-close: 1.5;
  --leading-tight: 1.2;
  --lead: 1.12em;
  --aside: 0.93em;
  --code: 0.8em;
  --title: 2rem;
  --heading: 1.1rem;
  --small: 0.875rem;
  --smaller: 0.75rem;

  --measure: 40rem;
  --gap: 1rem;
  --inset: 0.8em 1em;
  --radius: 8px;
  --pill: 99px;
  --hairline: 1px;
  --rule: 3px;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ground: #171614;
    --raised: #1e1d1a;
    --ink: #e8e4dc;
    --quiet: #9b958a;
    --line: #2f2c28;
    --accent: #9db4d6;
  }
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink);
  font: var(--text) / var(--leading) var(--serif);
  -webkit-font-smoothing: antialiased;
}

#glass {
  max-width: var(--measure);
  height: 100dvh;
  margin: 0 auto;
  padding: 0 var(--gap);
}

a {
  color: var(--accent);
}

code,
pre {
  font-family: var(--mono);
}

.glass-note {
  color: var(--quiet);
  font: var(--small) / var(--leading-close) var(--sans);
}

/* A place: what a mount draws whole. The way down to it stands above its
   title, quiet, in the sans. */

.place > nav {
  font: var(--small) / var(--leading-close) var(--sans);
  color: var(--quiet);
  margin-bottom: calc(var(--gap) * 2.5);
}

.place > nav a {
  color: inherit;
  text-decoration: none;
}

.place > nav a:hover {
  color: var(--ink);
}

.place > nav a + a::before {
  content: "›";
  margin: 0 0.5em;
  opacity: 0.6;
}

.place > h1 {
  font-size: var(--title);
  line-height: var(--leading-tight);
  font-weight: 600;
  margin: 0 0 calc(var(--gap) * 1.25);
  letter-spacing: -0.01em;
}

.place > h2 {
  font: var(--small) / var(--leading-close) var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--quiet);
  margin: calc(var(--gap) * 2.5) 0 calc(var(--gap) * 0.75);
}

.place pre {
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  padding: var(--inset);
  overflow: auto;
  max-height: 32rem;
  font-size: var(--code);
  line-height: var(--leading-close);
}

/* What is said about a thing beside it, small and quiet. */

.meta {
  display: block;
  font: var(--smaller) / var(--leading-close) var(--sans);
  color: var(--quiet);
}

/* A card: what a mount draws as a face, entered by a press. */

.card {
  display: block;
  padding: var(--gap) calc(var(--gap) * 1.15);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  background: var(--raised);
  cursor: pointer;
  transition: border-color 0.15s;
}

.card:hover,
.card:focus-visible {
  border-color: var(--quiet);
  outline: none;
}

.card .meta {
  margin-top: 0.5em;
}

/* A list: its items one under another. */

.list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: calc(var(--gap) * 0.75);
}

/* Panes, side by side, set off from each other by space. A pane scrolls
   within itself; its text starts at the top, and once it is scrolled the
   top fades, so what passes out of sight goes softly. */

:root {
  --pane-gap: calc(var(--gap) * 3);
  --fade: 3rem;
}

.panes {
  height: 100%;
}

.panes > .slot {
  overflow-y: auto;
  padding: calc(var(--gap) * 3) 0 calc(var(--gap) * 6);
  scrollbar-width: thin;
}

.panes > .slot[data-scrolled] {
  mask-image: linear-gradient(to bottom, transparent 0, #000 var(--fade));
}

/* A slot's chrome: what can be done with what stands in it. */

.chrome {
  position: fixed;
  z-index: 10;
  min-width: 14rem;
  padding: 0.35rem;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.18);
  font: var(--small) / var(--leading-close) var(--sans);
}

.chrome-title {
  padding: 0.4rem 0.6rem 0.3rem;
  color: var(--quiet);
  font-size: var(--smaller);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.chrome button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.45rem 0.6rem;
  border: 0;
  border-radius: calc(var(--radius) - 2px);
  background: none;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}

.chrome button:hover,
.chrome button:focus-visible {
  background: var(--line);
  outline: none;
}

.chrome button[aria-disabled="true"] {
  color: var(--quiet);
  cursor: default;
}

.chrome-why {
  padding: 0 0.6rem 0.45rem;
  color: var(--quiet);
  font-size: var(--smaller);
}

